-- Admin-configurable "Sell Your Device" catalog: models (with per-model
-- storage options) inside the existing fixed device-type buckets
-- (iphone/galaxy/ipad/laptop/tablet/other), plus an admin-managed list of
-- device problem/condition options. Device *type* buckets themselves stay
-- hardcoded in app code — only what's inside them is dynamic.
--
-- The separate "cosmetic condition" star-rating step is being removed from
-- the public form; device condition is now derived from the problem picker
-- alone. No schema change needed for that — it only touched client state.

create table sell_device_models (
  id uuid primary key default gen_random_uuid(),
  device_type text not null check (device_type in ('iphone','galaxy','ipad','laptop','tablet','other')),
  label text not null,
  image_url text,
  storage_options text[] not null default '{}',
  is_active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);
create index idx_sell_device_models_device_type on sell_device_models(device_type);

-- "None" is a fixed, frontend-only sentinel (clears every other selection)
-- and is never stored here — admins manage every other problem option.
create table sell_problem_options (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text,
  severity text not null default 'fair' check (severity in ('excellent','good','fair','poor')),
  is_active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

-- Seed: migrate the previously-hardcoded MODELS_DATA (150 models) so the
-- storefront doesn't go blank on cutover. Storage defaults to the same
-- per-device-type list every model used to share; admins can now edit each
-- model's list individually going forward.

-- Seed: migrate the previously-hardcoded PROBLEM_OPTIONS (minus "None",
-- which stays a fixed frontend sentinel).
